DEACTIVATED // Self-deactivated by user\n}\n\nenum BookingStatus {\n  PENDING // Customer submitted, artisan hasn't responded\n  CONFIRMED // Artisan accepted\n  IN_PROGRESS // Service is being delivered\n  COMPLETED // Service finished, payment settled\n  CANCELLED // Cancelled by either party\n  NO_SHOW // Customer didn't show up\n}\n\nenum PromotionType {\n  SPONSORED // Top carousel placement in directory\n  BOOST // Temporary search ranking boost (24-48 hrs)\n}\n\nenum PromotionStatus {\n  ACTIVE\n  EXPIRED\n  CANCELLED\n}\n\n// ─── Booking Thread Enums ─────────────────────────────────\n\nenum ThreadStatus {\n  OPEN // Inquiry sent, conversation ongoing\n  PROPOSAL_SENT // Artisan sent a structured proposal\n  BOOKED // Proposal accepted → Booking created\n  CLOSED // Manually closed by either party, or expired\n}\n\nenum ThreadMessageType {\n  TEXT // Free-form message\n  PROPOSAL // Structured proposal (price, date, time, etc.)\n  SYSTEM // Automated messages (\"Booking confirmed\", etc.)\n}\n\nenum SenderRole {\n  CLIENT\n  ARTISAN\n}\n\nenum PaymentMethod {\n  WALLET // In-app wallet escrow\n  OFFLINE // Cash, bank transfer, etc.\n  NONE // No payment attached yet\n}\n\nenum PaymentTiming {\n  UPFRONT // Pay before work starts\n  ON_COMPLETION // Pay after work is done\n}\n\nenum PaymentDisputedBy {\n  CLIENT\n  ARTISAN\n}\n\n// ─── Artisan Core ─────────────────────────────────────────\n\nmodel Artisan {\n  id        String  @id @default(uuid())\n  profile   Profile @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  profileId String  @unique\n  userId    String // Denormalized from profile for fast queries\n\n  // Artisan-specific fields\n  bio            String? // Artisan pitch (separate from profile.description)\n  status         ArtisanStatus @default(PENDING_REVIEW)\n  customCategory String? // Free-text when \"Others\" category is selected\n\n  // Verification\n  termsAcceptedAt DateTime?\n  activatedAt     DateTime? // When status changed to ACTIVE\n  suspendedReason String? // Admin reason for suspension\n\n  // Wallet\n  canReceiveWalletPayments Boolean @default(false) // KYC-verified wallet as of registration/last check\n\n  // Stats (denormalized for directory performance)\n  averageRating Decimal @default(0) @db.Decimal(3, 2) // 0.00 - 5.00\n  totalReviews  Int     @default(0)\n  totalBookings Int     @default(0)\n  totalEarnings Decimal @default(0) @db.Decimal(18, 4) // Lifetime earnings via platform\n\n  // Working hours: JSON array of { day: 0-6, open: \"09:00\", close: \"17:00\", isOpen: boolean }\n  workingHours Json?\n\n  // NEW Fields for Talent Sourcing\n  openToWork        Boolean     @default(true)\n  desiredJobTypes   JobType[] // What kind of work they want\n  desiredWorkModels WorkModel[] // Remote, On-site, etc.\n  skills            String[] // Array of skill tags for boolean search\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  // Relations\n  categories   ArtisanCategoryMap[]\n  services     ArtisanService[]\n  portfolio    PortfolioItem[]\n  bookings     Booking[]\n  reviews      Review[]\n  promotions   Promotion[]\n  threads      BookingThread[]\n  applications CpJobApplication[]\n  savedBy      CpSavedTalent[]\n\n  @@index([userId])\n  @@index([status])\n  @@index([averageRating])\n  @@index([createdAt])\n}\n\n// ─── Categories ───────────────────────────────────────────\n\nmodel ArtisanCategory {\n  id          String   @id @default(uuid())\n  name        String   @unique\n  slug        String   @unique // URL-safe: \"beauty-grooming\"\n  icon        String? // Emoji or icon identifier\n  description String?\n  order       Int      @default(0) // Display order in UI\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  artisans ArtisanCategoryMap[]\n\n  @@index([slug])\n  @@index([isActive, order])\n}\n\n// Many-to-many: an artisan can have 1–3 